const DAYS = { Mon: "lun", Tue: "mar", Wed: "mié", Thu: "jue", Fri: "vie", Sat: "sáb", Sun: "dom" };
const MONTHS = { Jan: "ene", Feb: "feb", Mar: "mar", Apr: "abr", May: "may", Jun: "jun", Jul: "jul", Aug: "ago", Sep: "sep", Oct: "oct", Nov: "nov", Dec: "dic" };

export const ES_RULES = [
  // "Sat 14 Nov" (dates written by the app in British English)
  [/^(Mon|Tue|Wed|Thu|Fri|Sat|Sun) (\d{1,2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)(\.?)$/, (m) => `${DAYS[m[1]]} ${m[2]} ${MONTHS[m[3]]}${m[4]}`],
  ...templateRules(ES_TEMPLATES)
];
